class Parent:
    def __init__(self):
        self.__secret_data = "I am a parent's secret."

    def access_parent_data(self):
        return self.__secret_data

class Child(Parent):
    def __init__(self):
        super().__init__() # Call the parent's constructor
        self.public_data = "I am a child's data."

    def try_to_access_secret(self):
        # This will fail because the name is mangled
        # It's not directly accessible as __secret_data in the child class
        try:
            print(f"Child trying to access secret: {self.__secret_data}")
        except AttributeError as e:
            print(f"AttributeError: {e}")

    def get_parent_data_via_method(self):
        # This works because the method is defined in the parent class
        return self.access_parent_data()

    def get_parent_data_via_mangled_name(self):
        # This is the only way to directly access it from the child
        return self._Parent__secret_data

# Create an instance of the child class
child_obj = Child()

# The child cannot directly access the mangled attribute
child_obj.try_to_access_secret()

# The child can access it indirectly via the parent's public method
print(f"Child accessing secret via parent method: {child_obj.get_parent_data_via_method()}")

# The child can access it directly, but only by using the mangled name
print(f"Child accessing secret via mangled name: {child_obj.get_parent_data_via_mangled_name()}")

