from abc import ABC, abstractmethod

class BaseCharacter(ABC):
    """An abstract base class for game characters."""

    @property
    @abstractmethod
    def name(self):
        """This property must be implemented by subclasses."""
        pass

    @name.setter
    @abstractmethod
    def name(self, value):
        """The setter for the name property."""
        pass

    def greet(self):
        print(f"Hello, my name is {self.name}.")

# --- Correct Implementation ---
class Knight(BaseCharacter):
    def __init__(self, name):
        self._name = name

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        if not isinstance(value, str) or not value.strip():
            raise ValueError("Name must be a non-empty string.")
        self._name = value

# Correctly implemented, this works
